# the Groups module's defaults for the built-in roles (plane.db.models.rbac.SYSTEM_ROLES), as of this migration
GROUP_PERMISSIONS = {
    "hr": {"view": "all", "create": "all", "edit": "all", "delete": "all"},
    "pm": {"view": "all", "create": "own", "edit": "own", "delete": "own"},
}


def give_built_in_roles_groups(apps, schema_editor):
    """HR manages every group and Project Managers their own, in existing workspaces too. Roles that already have
    a Groups permission are left alone."""
    Role = apps.get_model("db", "Role")
    RolePermission = apps.get_model("db", "RolePermission")
    for role in Role.objects.filter(key__in=GROUP_PERMISSIONS, deleted_at__isnull=True):
        if RolePermission.objects.filter(role=role, module="groups", deleted_at__isnull=True).exists():
            continue
        RolePermission.objects.bulk_create(
            [
                RolePermission(role_id=role.id, module="groups", action=action, scope=scope)
                for action, scope in GROUP_PERMISSIONS[role.key].items()
            ]
        )


